WITH remaining_keys AS (SELECT city, country FROM suppliers EXCEPT SELECT city, country FROM suppliers WHERE UPPER(supplier_name) LIKE '%ACI%'), kept_rows AS (SELECT s.* FROM suppliers s INNER JOIN remaining_keys k ON s.city = k.city AND s.country = k.country), not_flagged AS (SELECT s.* FROM kept_rows s WHERE EXISTS (SELECT 1 FROM products ch WHERE ch.supplier_id = s.id AND ARRAY_CONTAINS(ch.tags, 'new'))), scored AS (SELECT id, supplier_name, country, city, rating, ROUND(rating / SUM(rating) OVER (PARTITION BY city), 4) AS rating_share, SUM(rating) OVER (PARTITION BY city) AS city_sum_rating, COUNT(rating) OVER (PARTITION BY city) AS city_count_rating FROM not_flagged), with_windows AS (SELECT *, ROUND(city_sum_rating / SUM(city_sum_rating) OVER (PARTITION BY city), 4) AS city_sum_rating_share, AVG(city_count_rating) OVER (PARTITION BY country) AS country_avg_city_count_rating FROM scored), base AS (SELECT *, CONCAT(supplier_name, ' ', city) AS supplier_name_city FROM with_windows WHERE city_count_rating = 6) SELECT CASE WHEN city_sum_rating >= 20 THEN 'HIGH' ELSE 'LOW' END AS city_sum_rating_tier, city, COUNT(CASE WHEN country = 'TH' THEN 1 END) AS th_count, ROUND(AVG(country_avg_city_count_rating), 2) AS avg_country_avg_city_count_rating, APPROX_PERCENTILE(country_avg_city_count_rating, 0.9) AS country_avg_city_count_rating_p90, AVG(city_count_rating) FILTER (WHERE country = 'US') AS us_avg_city_count_rating FROM base GROUP BY CASE WHEN city_sum_rating >= 20 THEN 'HIGH' ELSE 'LOW' END, city ORDER BY th_count DESC NULLS FIRST
